use super::NUMBER_INPUT_EDIT_STATES;
use super::NUMBER_INPUT_FOCUS_HANDLES;
use super::NUMBER_INPUT_FOCUS_SUBS;
use gpui::{ElementId, Keystroke};

const MAX_NUMBER_INPUT_STATES: usize = 500;

/// Returns true if any NumberInput is currently in editing mode.
/// Useful for parent views that need to suppress keybindings during text entry.
pub fn is_number_input_editing() -> bool {
    NUMBER_INPUT_EDIT_STATES
        .with(|states| states.borrow().values().any(|state| state.borrow().editing))
}

/// Evict oldest entries from NumberInput thread-local storage if over the limit.
fn trim_number_input_storage() {
    NUMBER_INPUT_FOCUS_HANDLES.with(|handles| {
        let mut handles = handles.borrow_mut();
        while handles.len() > MAX_NUMBER_INPUT_STATES {
            if let Some(key) = handles.keys().next().cloned() {
                handles.remove(&key);
            }
        }
    });
    NUMBER_INPUT_EDIT_STATES.with(|states| {
        let mut states = states.borrow_mut();
        while states.len() > MAX_NUMBER_INPUT_STATES {
            if let Some(key) = states.keys().next().cloned() {
                states.remove(&key);
            }
        }
    });
    NUMBER_INPUT_FOCUS_SUBS.with(|subs| {
        let mut subs = subs.borrow_mut();
        while subs.len() > MAX_NUMBER_INPUT_STATES {
            if let Some(key) = subs.keys().next().cloned() {
                subs.remove(&key);
            }
        }
    });
}

/// Clean up thread-local state for a NumberInput element.
///
/// Call this when removing a NumberInput with a dynamic element ID to prevent
/// memory leaks. For static element IDs, cleanup is not necessary.
///
/// # Example
/// ```rust,ignore
/// // When removing a dynamically-created NumberInput
/// cleanup_number_input_state(&ElementId::Name(format!("input-{}", item_id).into()));
/// ```
pub fn cleanup_number_input_state(id: &ElementId) {
    NUMBER_INPUT_FOCUS_HANDLES.with(|handles| {
        handles.borrow_mut().remove(id);
    });
    NUMBER_INPUT_EDIT_STATES.with(|states| {
        states.borrow_mut().remove(id);
    });
    NUMBER_INPUT_FOCUS_SUBS.with(|subs| {
        subs.borrow_mut().remove(id);
    });
    trim_number_input_storage();
}

/// Convert a keystroke to an insertable character, explicitly handling the
/// space key so it works even when GPUI reports `key_char == None`.
pub(super) fn keystroke_to_char(keystroke: &Keystroke) -> Option<char> {
    if keystroke.key == "space" || keystroke.key == " " {
        Some(' ')
    } else {
        keystroke.key_char.as_ref().and_then(|s| s.chars().next())
    }
}

#[cfg(test)]
mod tests {
    use super::super::{NumberEditState, NUMBER_INPUT_EDIT_STATES, NUMBER_INPUT_FOCUS_HANDLES, NUMBER_INPUT_FOCUS_SUBS};
    use super::{cleanup_number_input_state, is_number_input_editing, keystroke_to_char, MAX_NUMBER_INPUT_STATES};
    use gpui::{ElementId, Keystroke, Modifiers, SharedString};

    #[test]
    fn test_keystroke_to_char_space() {
        let ks = Keystroke {
            key: "space".into(),
            key_char: None,
            modifiers: Modifiers::default(),
        };
        assert_eq!(keystroke_to_char(&ks), Some(' '));
    }

    #[test]
    fn keystroke_to_char_regular_key() {
        let ks = Keystroke {
            key: "1".into(),
            key_char: Some("1".into()),
            modifiers: Modifiers::default(),
        };
        assert_eq!(keystroke_to_char(&ks), Some('1'));
    }

    #[test]
    fn is_number_input_editing_reflects_state() {
        NUMBER_INPUT_EDIT_STATES.with(|states| states.borrow_mut().clear());
        assert!(!is_number_input_editing());

        NUMBER_INPUT_EDIT_STATES.with(|states| {
            let mut states = states.borrow_mut();
            states.insert(
                ElementId::Name(SharedString::from("num-edit")),
                std::rc::Rc::new(std::cell::RefCell::new(NumberEditState::new("5"))),
            );
        });
        assert!(is_number_input_editing());
        NUMBER_INPUT_EDIT_STATES.with(|states| states.borrow_mut().clear());
    }

    #[test]
    fn cleanup_number_input_state_removes_edit_state() {
        let id = ElementId::Name(SharedString::from("cleanup-test"));
        NUMBER_INPUT_EDIT_STATES.with(|states| {
            states.borrow_mut().insert(
                id.clone(),
                std::rc::Rc::new(std::cell::RefCell::new(NumberEditState::default())),
            );
        });

        cleanup_number_input_state(&id);
        assert!(!NUMBER_INPUT_EDIT_STATES.with(|s| s.borrow().contains_key(&id)));
    }

    #[test]
    fn trim_number_input_storage_evicts_oldest() {
        NUMBER_INPUT_FOCUS_HANDLES.with(|h| h.borrow_mut().clear());
        NUMBER_INPUT_EDIT_STATES.with(|s| s.borrow_mut().clear());
        NUMBER_INPUT_FOCUS_SUBS.with(|s| s.borrow_mut().clear());

        for i in 0..=MAX_NUMBER_INPUT_STATES {
            NUMBER_INPUT_EDIT_STATES.with(|s| {
                s.borrow_mut().insert(
                    ElementId::Name(SharedString::from(format!("s-{i}"))),
                    std::rc::Rc::new(std::cell::RefCell::new(NumberEditState::default())),
                );
            });
        }

        cleanup_number_input_state(&ElementId::Name(SharedString::from("unused")));
        let count = NUMBER_INPUT_EDIT_STATES.with(|s| s.borrow().len());
        assert!(count <= MAX_NUMBER_INPUT_STATES);
    }

}
